"""Write evaluation results to Excel: eval + review sheets (reports are generated by kb-report)."""

import os

import pandas as pd
from openpyxl import Workbook
from openpyxl.styles import Font, Alignment, PatternFill, Border, Side

from scripts.eval_stats import (
    WEIGHTS,
    LANGUAGE_META, score_headers,
)
from scripts.excel_style import HEADER_FONT, HEADER_FILL, HEADER_ALIGN, auto_width


def _meta(language: str):
    return LANGUAGE_META.get(language, LANGUAGE_META["en"])


_THIN_BORDER = Border(
    left=Side(style="thin"), right=Side(style="thin"),
    top=Side(style="thin"), bottom=Side(style="thin"),
)
_SECTION_FONT = Font(bold=True, size=11, color="1F4E79")
_SECTION_FILL = PatternFill("solid", fgColor="D6E4F0")


class ExcelWriter:
    def __init__(self, df: pd.DataFrame, results: list, columns: dict, language: str = "en"):
        self.df = df
        self.results = results
        self.columns = columns
        self.language = language
        self.wb = Workbook()
        meta = _meta(language)
        self.headers = score_headers(language)
        self.dim_keys = meta.dims + [meta.summary_key]
        self.score_key = meta.score_key
        self.reason_key = meta.reason_key
        self.review_sheet_name = meta.review_sheet_name
        self.weighted_label = meta.weighted_label
        self.summary_label = meta.summary_key

    def write_eval_sheet(self):
        ws = self.wb.active
        ws.title = _meta(self.language).eval_sheet_name

        df_cols = list(self.df.columns)
        for c_idx, col_name in enumerate(df_cols, 1):
            cell = ws.cell(row=1, column=c_idx, value=str(col_name))
            cell.font = HEADER_FONT
            cell.fill = HEADER_FILL
            cell.alignment = HEADER_ALIGN

        for r_idx, (_, row) in enumerate(self.df.iterrows()):
            for c_idx, col_name in enumerate(df_cols, 1):
                val = row[col_name]
                if isinstance(val, float) and pd.isna(val):
                    val = ""
                ws.cell(row=r_idx + 2, column=c_idx, value=val)

        original_col_count = len(df_cols)

        for i, (score_hdr, reason_hdr) in enumerate(self.headers):
            col_score = original_col_count + 1 + i * 2
            col_reason = col_score + 1
            for c, val in ((col_score, score_hdr), (col_reason, reason_hdr)):
                cell = ws.cell(row=1, column=c, value=val)
                cell.font = HEADER_FONT
                cell.fill = HEADER_FILL
                cell.alignment = HEADER_ALIGN

        wavg_col = original_col_count + 1 + len(self.headers) * 2
        summary_col = wavg_col + 1
        weighted_label = self.weighted_label
        summary_label = self.summary_label
        for c, val in ((wavg_col, weighted_label), (summary_col, summary_label)):
            cell = ws.cell(row=1, column=c, value=val)
            cell.font = HEADER_FONT
            cell.fill = HEADER_FILL
            cell.alignment = HEADER_ALIGN

        result_map = {r["index"]: r for r in self.results}

        for idx_val, result_item in result_map.items():
            row_num = idx_val + 2
            result = result_item.get("result") or {}

            for dim_i, dim_key in enumerate(self.dim_keys[:-1]):
                col_score = original_col_count + 1 + dim_i * 2
                col_reason = col_score + 1
                dim_data = result.get(dim_key, {})
                if not isinstance(dim_data, dict):
                    dim_data = {}
                s = dim_data.get(self.score_key, "")
                r = dim_data.get(self.reason_key, "")
                try:
                    s_num = int(s)
                except (TypeError, ValueError):
                    s_num = None
                if s_num is not None:
                    s = s_num
                if r in (None, "None", "null"):
                    r = ""
                ws.cell(row=row_num, column=col_score, value=s if s != "" else None)
                ws.cell(row=row_num, column=col_reason, value=r if r else "")

            score_cols = [original_col_count + 1 + dim_i * 2 for dim_i in range(5)]
            weighted_sum = 0.0
            has_valid_score = False
            for dim_i in range(5):
                dim_data = result.get(self.dim_keys[dim_i], {})
                if not isinstance(dim_data, dict):
                    dim_data = {}
                s = dim_data.get(self.score_key, 0)
                try:
                    weighted_sum += float(s) * WEIGHTS[dim_i]
                    has_valid_score = True
                except (TypeError, ValueError):
                    pass
            # 只有当至少有一个有效分数时才写入加权均分，否则写 None
            ws.cell(row=row_num, column=wavg_col, value=round(weighted_sum, 2) if has_valid_score else None)

            summary_val = result.get(self.dim_keys[-1], "")
            if summary_val is None or str(summary_val).strip() in ("None", "null", ""):
                summary_val = ""
            elif isinstance(summary_val, str):
                import re
                cleaned = re.sub(r'\bNone\b', '', summary_val)
                cleaned = re.sub(r'\[Low Score Dimensions\]\s*\[Improvement Suggestions\]', '', cleaned)
                cleaned = re.sub(r'\[Low Score Dimensions\]\s*$', '', cleaned)
                cleaned = re.sub(r'\[Improvement Suggestions\]\s*$', '', cleaned)
                cleaned = re.sub(r'\n{3,}', '\n\n', cleaned)
                if cleaned.strip() in ('', '[Low Score Dimensions]', '[Improvement Suggestions]',
                                       '[Low Score Dimensions]\n[Improvement Suggestions]'):
                    summary_val = ""
                else:
                    summary_val = cleaned.strip()
            ws.cell(row=row_num, column=summary_col, value=summary_val)

        auto_width(ws)


    def write_review_sheet(self, review_df: pd.DataFrame):
        if review_df.empty:
            return
        ws = self.wb.create_sheet(self.review_sheet_name)

        cols = list(review_df.columns)
        for c, col_name in enumerate(cols, 1):
            cell = ws.cell(row=1, column=c, value=str(col_name))
            cell.font = HEADER_FONT
            cell.fill = HEADER_FILL
            cell.alignment = HEADER_ALIGN

        for r_idx, (_, row) in enumerate(review_df.iterrows()):
            for c_idx, col_name in enumerate(cols, 1):
                val = row[col_name]
                if isinstance(val, float) and pd.isna(val):
                    val = ""
                cell = ws.cell(row=r_idx + 2, column=c_idx, value=val)

        auto_width(ws)

    def save(self, output_path: str) -> str:
        self.write_eval_sheet()
        self.wb.save(output_path)
        return output_path
